try:
    manifest = json.loads(text)
except (json.JSONDecodeError, TypeError) as exc:
    raise ValueError(str(exc)) from exc

if not isinstance(manifest, dict):
    raise ValueError("manifest must be a JSON object")

# --- bundle_id ---
bundle_id = manifest.get("bundle_id")
if not isinstance(bundle_id, str) or not bundle_id:
    raise ValueError("bundle_id must be a nonempty string")

# --- files ---
files = manifest.get("files")
if not isinstance(files, list):
    raise ValueError("files must be a list")

total_bytes = 0
for entry in files:
    if not isinstance(entry, dict):
        raise ValueError("each file entry must be an object")

    path = entry.get("path")
    if not isinstance(path, str) or not path:
        raise ValueError("path must be a nonempty string")

    size = entry.get("size_bytes")
    # reject booleans (bool is a subclass of int), floats, and non-ints
    if isinstance(size, bool) or not isinstance(size, int):
        raise ValueError("size_bytes must be an integer")
    if size < 0:
        raise ValueError("size_bytes must be nonnegative")

    total_bytes += size

return {
    "bundle_id": bundle_id,
    "file_count": len(files),
    "total_bytes": total_bytes,
}

